            continue
        for p in picks:
            idx = int(round((p.peak_time - t0) / dt))
            if idx < 0 or idx >= 12000:
                continue
            prob = getattr(p, "peak_value", 1.0) or 1.0
            if p.phase in all_picks:
                all_picks[p.phase].append((idx, float(prob), name))

    # Cluster picks by proximity; require agreement from >= MIN_VOTES models.
    # This favors precision (agreement) while retaining ensemble recall.
    for phase, plist in all_picks.items():
        if not plist:
            continue
        plist.sort()
        clusters = [[plist[0]]]
        for item in plist[1:]:
            if item[0] - clusters[-1][-1][0] <= MERGE_TOL:
                clusters[-1].append(item)
            else:
                clusters.append([item])
        for cluster in clusters:
            distinct_models = {c[2] for c in cluster}
            best = max(cluster, key=lambda x: x[1])
            # Accept if either (a) confirmed by >=2 models, or
