        for p in picks:
            idx = int(round((p.peak_time - t0) / dt))
            if idx < 0 or idx >= 12000:
                continue
            prob = getattr(p, "peak_value", 1.0) or 1.0
            if p.phase in all_picks:
                all_picks[p.phase].append((idx, float(prob)))

    # Merge picks within MERGE_TOL, keep highest-probability pick per cluster
    for phase, plist in all_picks.items():
        if not plist:
            continue
        plist.sort()
        clusters = [[plist[0]]]
